const items = [];

// Parse OLX
try {
  const olxData = $('Fetch OLX').first().json;
  const olxAds = olxData.data?.ads || olxData.ads || [];
  for (const ad of olxAds) {
    const price = ad.price?.value?.raw || 0;
    if (price < 300000 || price > 800000) continue;
    items.push({
      source: 'olx',
      title: ad.title || '',
      price: price,
      location: ad.location?.name || ad.locations?.[0]?.name || '',
      url: `https://www.olx.co.id/item/${ad.url || ad.id}`,
      description: ad.description || '',
      images: (ad.images || []).slice(0, 3).map(i => i?.url || ''),
      scraped_at: new Date().toISOString()
    });
  }
} catch(e) { console.error('OLX parse error:', e.message); }

// Parse 99.co
try {
  const coData = $('Fetch 99.co').first().json;
  const listings = coData.listings || coData.data || [];
  for (const listing of listings) {
    const price = listing.price_formatted?.raw || listing.price || 0;
    if (price < 300000 || price > 800000) continue;
    items.push({
      source: '99co',
      title: listing.title || '',
      price: price,
      location: listing.address || listing.location || '',
      url: `https://www.99.co/id/dijual/${listing.slug || listing.id}`,
      description: listing.description || '',
      images: (listing.photos || []).slice(0, 3).map(p => p.url || p),
      scraped_at: new Date().toISOString()
    });
  }
} catch(e) { console.error('99.co parse error:', e.message); }

return items;
